    chosen_key["updated_at"] = now_iso

    # create vacation plan with status planning (allowed initial)
    # id convention: vp_<hash>
    vp_id = "vp_" + hashlib.sha256((now_iso + "|" + chosen_key["id"] + "|" + user_prompt.strip()).encode("utf-8")).hexdigest()[:24]
    # ensure uniqueness: if collision, salt with counter
    existing_ids = {p.get("id") for p in plans if isinstance(p, dict)}
    if vp_id in existing_ids:
        salt = 1
        while True:
            cand = "vp_" + hashlib.sha256((now_iso + "|" + chosen_key["id"] + "|" + user_prompt.strip() + f"|{salt}").encode("utf-8")).hexdigest()[:24]
            if cand not in existing_ids:
                vp_id = cand
                break
            salt += 1

    plan_row = {
        "id": vp_id,
        "api_key_id": chosen_key["id"],
        "status": "planning",
        "user_prompt": user_prompt,
        "plan_title": plan_title,
