            "request_id": req_id
        }
    }

def get_current_api_key(api_key, **_extra):
    import json, os, datetime, hashlib, secrets, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0450000" if __import__("os").path.isdir("./environment_mix/0450000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    api_keys = _load("api_keys.json")
    reqs = _load("location_search_requests.json")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.utcfromtimestamp(s)
        if isinstance(s, str):
            x = s.strip()
            if x.endswith("Z"):
                x = x[:-1]
            try:
                return datetime.datetime.fromisoformat(x)
            except Exception:
                return None
        return None

    def _ensure_window(krow):
        # reset daily window if needed (day boundary from usage_window_start)
        ws = _parse_dt(krow.get("usage_window_start"))
        if ws is None or ws > now:
            ws = now
            krow["usage_window_start"] = now_iso
            krow["daily_requests_used"] = int(krow.get("daily_requests_used") or 0)
            return True
        if ws.date() != now.date():
            krow["usage_window_start"] = now_iso
            krow["daily_requests_used"] = 0
            return True
        return False

    def _hash_presented_key(k):
        # vendor store contains hash; we must authenticate by matching plaintext OR id if ever stored
        # Try common digests of the presented key to match stored key_hash.
        b = k.encode("utf-8")
        cands = set()
        cands.add(hashlib.sha256(b).hexdigest())
        cands.add(hashlib.sha1(b).hexdigest())
        cands.add(hashlib.md5(b).hexdigest())
        # Sometimes "key_hash" can actually be stored as-is (not ideal); include raw
        cands.add(k)
        return cands

    presented = api_key.strip()
    key_row = None
    cands = _hash_presented_key(presented)
    for r in api_keys:
        if not isinstance(r, dict):
            continue
        if r.get("id") == presented:
            key_row = r
            break
        kh = r.get("key_hash")
        if isinstance(kh, str) and kh in cands:
            key_row = r
            break

    # Log helper (this tool isn't in enum; do not write invalid enum to location_search_requests)
    def _record_usage_only(krow, succeeded):
        changed = _ensure_window(krow)
        if succeeded:
            krow["daily_requests_used"] = int(krow.get("daily_requests_used") or 0) + 1
            krow["last_used_at"] = now_iso
        krow["updated_at"] = now_iso
        return changed

    if key_row is None:
        return _err("UNAUTHORIZED", "Missing or invalid API key")

    if key_row.get("status") == "revoked":
        # Tool spec says FORBIDDEN, but allowed codes list doesn't include it; use UNAUTHORIZED with detail.
        return _err("UNAUTHORIZED", "API key is revoked", reason="revoked")

    # Enforce quota dynamics: even this call counts as a request
    changed = _ensure_window(key_row)
    limit = key_row.get("daily_request_limit")
    used = int(key_row.get("daily_requests_used") or 0)
    if not isinstance(limit, int) or limit <= 0:
        return _err("VALIDATION_ERROR", "API key configuration invalid: daily_request_limit must be > 0")
    if used >= limit:
        # Not logged (enum restriction), but enforce quota
        key_row["updated_at"] = now_iso
        _save("api_keys.json", api_keys)
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded", daily_request_limit=limit, daily_requests_used=used)

    _record_usage_only(key_row, succeeded=True)
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "api_key": {
            "id": key_row.get("id"),
            "label": key_row.get("label"),
            "status": key_row.get("status"),
            "daily_request_limit": key_row.get("daily_request_limit"),
            "daily_requests_used": key_row.get("daily_requests_used"),
            "usage_window_start": key_row.get("usage_window_start"),
            "last_used_at": key_row.get("last_used_at"),
            "created_at": key_row.get("created_at"),
            "updated_at": key_row.get("updated_at"),
        },
        "request": {
            "latency_ms": latency_ms,
            "timestamp": now_iso,
        }
    }

def get_vacation_plan(api_key, vacation_plan_id, **_extra):
    import json, os, datetime, hashlib, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0450000" if __import__("os").path.isdir("./environment_mix/0450000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(vacation_plan_id, str) or not re.match(r"^[A-Za-z0-9_-]+$", vacation_plan_id):
        return _err("VALIDATION_ERROR", "vacation_plan_id is malformed")

    api_keys = _load("api_keys.json")
    plans = _load("vacation_plans.json")
    reqs = _load("location_search_requests.json")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.utcfromtimestamp(s)
        if isinstance(s, str):
            x = s.strip()
            if x.endswith("Z"):
                x = x[:-1]
            try:
                return datetime.datetime.fromisoformat(x)
            except Exception:
                return None
        return None

    def _ensure_window(krow):
        ws = _parse_dt(krow.get("usage_window_start"))
        if ws is None or ws > now:
            krow["usage_window_start"] = now_iso
            krow["daily_requests_used"] = int(krow.get("daily_requests_used") or 0)
            return True
        if ws.date() != now.date():
            krow["usage_window_start"] = now_iso
            krow["daily_requests_used"] = 0
            return True
        return False

    def _hash_presented_key(k):
        b = k.encode("utf-8")
        return {hashlib.sha256(b).hexdigest(), hashlib.sha1(b).hexdigest(), hashlib.md5(b).hexdigest(), k}

    # Authenticate
    presented = api_key.strip()
    cands = _hash_presented_key(presented)
    key_row = None
    for r in api_keys:
        if not isinstance(r, dict):
            continue
        if r.get("id") == presented:
            key_row = r
            break
        kh = r.get("key_hash")
        if isinstance(kh, str) and kh in cands:
            key_row = r
            break
    if key_row is None:
        return _err("UNAUTHORIZED", "Missing or invalid API key")

    # Create request log row (tool enum includes get_location_details_tool etc; this tool is not in enum).
    # Cannot write invalid tool_name; enforce quota/usage but skip request log to satisfy enum constraint.
    # Still enforce quotas/counters.
    _ensure_window(key_row)
    limit = key_row.get("daily_request_limit")
    used = int(key_row.get("daily_requests_used") or 0)
    if not isinstance(limit, int) or limit <= 0:
        return _err("VALIDATION_ERROR", "API key configuration invalid: daily_request_limit must be > 0")
    if used >= limit:
        key_row["updated_at"] = now_iso
        _save("api_keys.json", api_keys)
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded", daily_request_limit=limit, daily_requests_used=used)

    # Find plan
    plan = None
    for p in plans:
        if isinstance(p, dict) and p.get("id") == vacation_plan_id:
            plan = p
            break
    if plan is None:
        # count usage as succeeded? In real services, even 404 counts. We'll count as succeeded request.
        key_row["daily_requests_used"] = used + 1
        key_row["last_used_at"] = now_iso
        key_row["updated_at"] = now_iso
        _save("api_keys.json", api_keys)
        return _err("NOT_FOUND", "Vacation plan not found")

    if plan.get("api_key_id") != key_row.get("id"):
        key_row["daily_requests_used"] = used + 1
        key_row["last_used_at"] = now_iso
        key_row["updated_at"] = now_iso
        _save("api_keys.json", api_keys)
        # spec says FORBIDDEN vs NOT_FOUND; allowed codes exclude FORBIDDEN. Use NOT_FOUND to avoid disclosing.
        return _err("NOT_FOUND", "Vacation plan not found")

    # Success: count usage
    key_row["daily_requests_used"] = used + 1
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "vacation_plan": {
            "id": plan.get("id"),
            "status": plan.get("status"),
            "user_prompt": plan.get("user_prompt"),
            "plan_title": plan.get("plan_title"),
            "start_date": plan.get("start_date"),
            "end_date": plan.get("end_date"),
            "destination_query": plan.get("destination_query"),
            "generated_plan_text": plan.get("generated_plan_text"),
            "generated_plan_json": plan.get("generated_plan_json"),
            "error_code": plan.get("error_code"),
            "error_message": plan.get("error_message"),
            "created_at": plan.get("created_at"),
            "updated_at": plan.get("updated_at"),
        },
        "request": {
            "latency_ms": latency_ms,
            "timestamp": now_iso,
        }
    }

def list_vacation_plans(api_key, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, hashlib, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0450000" if __import__("os").path.isdir("./environment_mix/0450000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    allowed_status = {"draft", "planning", "ready", "cancelled", "failed"}

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if status is not None and status not in allowed_status:
        return _err("VALIDATION_ERROR", "status must be one of: draft, planning, ready, cancelled, failed")
    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")

    api_keys = _load("api_keys.json")
    plans = _load("vacation_plans.json")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.utcfromtimestamp(s)
        if isinstance(s, str):
            x = s.strip()
            if x.endswith("Z"):
                x = x[:-1]
            try:
                return datetime.datetime.fromisoformat(x)
            except Exception:
                return None
        return None

    def _ensure_window(krow):
        ws = _parse_dt(krow.get("usage_window_start"))
        if ws is None or ws > now:
            krow["usage_window_start"] = now_iso
            krow["daily_requests_used"] = int(krow.get("daily_requests_used") or 0)
            return True
        if ws.date() != now.date():
            krow["usage_window_start"] = now_iso
            krow["daily_requests_used"] = 0
            return True
        return False

    def _hash_presented_key(k):
        b = k.encode("utf-8")
        return {hashlib.sha256(b).hexdigest(), hashlib.sha1(b).hexdigest(), hashlib.md5(b).hexdigest(), k}

    # Authenticate
    presented = api_key.strip()
    cands = _hash_presented_key(presented)
    key_row = None
    for r in api_keys:
        if not isinstance(r, dict):
            continue
        if r.get("id") == presented:
            key_row = r
            break
        kh = r.get("key_hash")
        if isinstance(kh, str) and kh in cands:
            key_row = r
            break
    if key_row is None:
        return _err("UNAUTHORIZED", "Missing or invalid API key")

    # Enforce quota (this call counts)
    _ensure_window(key_row)
    limit_daily = key_row.get("daily_request_limit")
    used = int(key_row.get("daily_requests_used") or 0)
    if not isinstance(limit_daily, int) or limit_daily <= 0:
        return _err("VALIDATION_ERROR", "API key configuration invalid: daily_request_limit must be > 0")
    if used >= limit_daily:
        key_row["updated_at"] = now_iso
        _save("api_keys.json", api_keys)
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded", daily_request_limit=limit_daily, daily_requests_used=used)

    # Cursor handling: opaque base64url of "created_at|id"
    after_created_at = None
    after_id = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            padded = cursor.strip() + "=" * (-len(cursor.strip()) % 4)
            raw = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8")
            parts = raw.split("|", 1)
            if len(parts) != 2:
                return _err("VALIDATION_ERROR", "Malformed cursor")
            after_created_at, after_id = parts[0], parts[1]
            if _parse_dt(after_created_at) is None or not after_id:
                return _err("VALIDATION_ERROR", "Malformed cursor")
        except Exception:
            return _err("VALIDATION_ERROR", "Malformed cursor")

    # Filter by owner and status
    owned = [p for p in plans if isinstance(p, dict) and p.get("api_key_id") == key_row.get("id")]
    if status is not None:
        owned = [p for p in owned if p.get("status") == status]

    # Sort by created_at desc then id desc
    def _sort_key(p):
        dt = _parse_dt(p.get("created_at")) or datetime.datetime(1970, 1, 1)
        return (dt, str(p.get("id") or ""))

    owned.sort(key=_sort_key, reverse=True)

    # Apply cursor: return items strictly "before" the cursor in the sort order
    if after_created_at is not None:
        cur_dt = _parse_dt(after_created_at) or datetime.datetime(1970, 1, 1)
        cur_id = after_id
        filtered = []
        for p in owned:
            pdt = _parse_dt(p.get("created_at")) or datetime.datetime(1970, 1, 1)
            pid = str(p.get("id") or "")
            if (pdt, pid) < (cur_dt, cur_id):
                filtered.append(p)
        owned = filtered

    total = len(owned)
    page = owned[:limit]
    has_more = total > len(page)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_created = last.get("created_at") or "1970-01-01T00:00:00Z"
        last_id = str(last.get("id") or "")
        token = f"{last_created}|{last_id}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(token).decode("utf-8").rstrip("=")

    # Count usage and persist
    key_row["daily_requests_used"] = used + 1
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "vacation_plans": [
            {
                "id": p.get("id"),
                "status": p.get("status"),
                "plan_title": p.get("plan_title"),
                "destination_query": p.get("destination_query"),
                "start_date": p.get("start_date"),
                "end_date": p.get("end_date"),
                "created_at": p.get("created_at"),
                "updated_at": p.get("updated_at"),
            }
            for p in page
        ],
        "page": {
            "limit": limit,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
        "request": {
            "latency_ms": latency_ms,
            "timestamp": now_iso,
        }
    }

def update_vacation_plan_status(api_key, vacation_plan_id, status, error_code=None, error_message=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0450000" if __import__("os").path.isdir("./environment_mix/0450000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    allowed_status = ["draft", "planning", "ready", "cancelled", "failed"]
    transitions = {
        "draft": ["planning", "cancelled"],
        "planning": ["ready", "failed", "cancelled"],
        "ready": [],
        "cancelled": [],
        "failed": [],
    }

    def _rows(x):
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        if isinstance(x, list):
            return x
        return []

    def _save_rows(filename, rows):
        existing = _load(filename)
        if isinstance(existing, dict):
            existing["rows"] = rows
            _save(filename, existing)
        else:
            _save(filename, rows)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        v = s.strip()
        if v.endswith("Z"):
            v = v[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(v)
        except Exception:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _start_of_day_utc(dt):
        return dt.astimezone(datetime.timezone.utc).replace(hour=0, minute=0, second=0, microsecond=0)

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{os.getpid()}_{time.time_ns()}"

    # ---------- validate inputs ----------
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(vacation_plan_id, str) or not re.match(r"^[A-Za-z0-9_-]+$", vacation_plan_id):
        return _err("VALIDATION_ERROR", "vacation_plan_id is malformed")
    if not isinstance(status, str) or status not in allowed_status:
        return _err("VALIDATION_ERROR", "status must be one of: draft, planning, ready, cancelled, failed")
    if error_code is not None and not isinstance(error_code, str):
        return _err("VALIDATION_ERROR", "error_code must be a string when provided")
    if error_message is not None and not isinstance(error_message, str):
        return _err("VALIDATION_ERROR", "error_message must be a string when provided")
    if status == "failed" and (error_code is None or not str(error_code).strip()):
        return _err("VALIDATION_ERROR", "error_code is required when transitioning to failed")

    # ---------- authenticate api_key ----------
    api_keys_raw = _load("api_keys.json")
    api_keys = _rows(api_keys_raw)

    # Per contract: authenticate against client-visible value or id (NOT key_hash)
    key_row = None
    for r in api_keys:
        if isinstance(r, dict) and r.get("id") == api_key:
            key_row = r
            break
    if key_row is None:
        # No usable credential anywhere matches the presented value
        return _err("UNAUTHORIZED", "Invalid API key")

    # Prepare request log row (must exist for every invocation)
    req_id = _gen_id("tsrq")
    req = {
        "id": req_id,
        "api_key_id": key_row.get("id"),
        "tool_name": "plan_vacation",
        "latitude": None,
        "longitude": None,
        "category": None,
        "location_id": None,
        "status": "received",
        "error_code": None,
        "error_message": None,
        "response_count": None,
        "latency_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    reqs_raw = _load("location_search_requests.json")
    reqs = _rows(reqs_raw)
    reqs.append(req)
    _save_rows("location_search_requests.json", reqs)

    def _finalize(status_value, error_code_value=None, error_message_value=None, response_count_value=None):
        req["status"] = status_value
        req["error_code"] = error_code_value
        req["error_message"] = error_message_value
        req["response_count"] = response_count_value
        req["latency_ms"] = max(0, int((time.time() - t0) * 1000))
        req["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        _save_rows("location_search_requests.json", reqs)

    # ---------- rate limit / quota enforcement ----------
    if key_row.get("status") != "active":
        _finalize("failed", "unauthorized", "API key is not active.")
        return _err("UNAUTHORIZED", "API key is not active", request_id=req_id)

    # Reset usage window if needed (daily)
    window_start = _parse_dt(key_row.get("usage_window_start"))
    if window_start is None:
        window_start = _start_of_day_utc(now)
        key_row["usage_window_start"] = window_start.isoformat().replace("+00:00", "Z")
        key_row["daily_requests_used"] = 0

    if _start_of_day_utc(now) > _start_of_day_utc(window_start):
        key_row["usage_window_start"] = _start_of_day_utc(now).isoformat().replace("+00:00", "Z")
        key_row["daily_requests_used"] = 0

    try:
        daily_limit = int(key_row.get("daily_request_limit"))
        daily_used = int(key_row.get("daily_requests_used"))
    except Exception:
        _finalize("failed", "quota_config_invalid", "API key quota configuration is invalid.")
        return _err("VALIDATION_ERROR", "API key quota configuration is invalid", request_id=req_id)

    if daily_limit <= 0 or daily_used < 0:
        _finalize("failed", "quota_config_invalid", "API key quota configuration is invalid.")
        return _err("VALIDATION_ERROR", "API key quota configuration is invalid", request_id=req_id)

    if daily_used >= daily_limit:
        _finalize("rate_limited", "quota_exceeded", "Daily request limit reached for this API key.")
        return _err("QUOTA_EXCEEDED", "Daily request limit reached for this API key.", request_id=req_id)

    # count this request against quota (request is being processed)
    key_row["daily_requests_used"] = daily_used + 1
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save_rows("api_keys.json", api_keys)

    # ---------- perform mutation ----------
    plans_raw = _load("vacation_plans.json")
    plans = _rows(plans_raw)

    plan = None
    for r in plans:
        if isinstance(r, dict) and r.get("id") == vacation_plan_id:
            plan = r
            break
    if plan is None:
        _finalize("failed", "not_found", "Vacation plan not found.")
        return _err("NOT_FOUND", "Vacation plan not found.", request_id=req_id)

    # Ownership check: must be owned by calling key
    if plan.get("api_key_id") != key_row.get("id"):
        _finalize("failed", "forbidden", "Vacation plan not owned by this API key.")
        return _err("UNAUTHORIZED", "Vacation plan not owned by this API key.", request_id=req_id)

    current = plan.get("status")
    if current not in allowed_status:
        _finalize("failed", "invalid_transition", f"Plan is in an unknown status '{current}'.")
        return _err("INVALID_TRANSITION", f"Plan is in an unknown status '{current}'.", request_id=req_id)

    if status == current:
        # idempotent: still a successful invocation with effect = no state change but explicit confirm
        # However contract says "NO SUCCESS WITHOUT EFFECT" for mutations that matched no row; this matched a row.
        # We'll still update updated_at and failure fields if relevant, so there is an effect.
        plan["updated_at"] = now_iso
        if status == "failed":
            plan["error_code"] = error_code
            plan["error_message"] = error_message
        _save_rows("vacation_plans.json", plans)
        _finalize("succeeded", None, None, 1)
        return {
            "vacation_plan": plan,
            "request_id": req_id,
        }

    if status not in transitions.get(current, []):
        _finalize("failed", "invalid_transition", f"Cannot transition vacation plan from {current} to {status}.")
        return _err("INVALID_TRANSITION", f"Cannot transition vacation plan from {current} to {status}.", request_id=req_id)

    # enforce failed requires error_code
    if status == "failed":
        plan["error_code"] = error_code
        plan["error_message"] = error_message
    else:
        # if leaving failed isn't allowed anyway; on non-failed statuses, clear errors
        plan["error_code"] = None
        plan["error_message"] = None

    plan["status"] = status
    plan["updated_at"] = now_iso
    _save_rows("vacation_plans.json", plans)

    _finalize("succeeded", None, None, 1)
    return {
        "vacation_plan": plan,
        "request_id": req_id,
    }

def upsert_vacation_plan_item(api_key, vacation_plan_id, day_index, sequence, item_type, title, vacation_plan_item_id=None, location_id=None, starts_at=None, ends_at=None, notes=None, status=None, **_extra):
