        "removed": set(),
    }

    def _rows(x):
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        if isinstance(x, list):
            return x
        return []

    def _save_rows(filename, rows):
        existing = _load(filename)
        if isinstance(existing, dict):
            existing["rows"] = rows
            _save(filename, existing)
        else:
            _save(filename, rows)

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string")
        v = s.strip()
        if v.endswith("Z"):
            v = v[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(v)
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string")
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z"), None

    def _gen_id(prefix):
