        key_row["daily_requests_used"] = 0

    if _start_of_day_utc(now) > _start_of_day_utc(window_start):
        key_row["usage_window_start"] = _start_of_day_utc(now).isoformat().replace("+00:00", "Z")
        key_row["daily_requests_used"] = 0

    try:
        daily_limit = int(key_row.get("daily_request_limit"))
        daily_used = int(key_row.get("daily_requests_used"))
    except Exception:
        _finalize("failed", "quota_config_invalid", "API key quota configuration is invalid.")
        return _err("VALIDATION_ERROR", "API key quota configuration is invalid", request_id=req_id)

    if daily_used >= daily_limit:
        _finalize("rate_limited", "quota_exceeded", "Daily request limit reached for this API key.")
        return _err("QUOTA_EXCEEDED", "Daily request limit reached for this API key.", request_id=req_id)

    key_row["daily_requests_used"] = daily_used + 1
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save_rows("api_keys.json", api_keys)

    # ---------- check foreign keys & plan writability ----------
    plans_raw = _load("vacation_plans.json")
    plans = _rows(plans_raw)
    plan = None
    for r in plans:
        if isinstance(r, dict) and r.get("id") == vacation_plan_id:
            plan = r
            break
    if plan is None:
        _finalize("failed", "not_found", "Vacation plan not found.")
        return _err("NOT_FOUND", "Vacation plan not found.", request_id=req_id)

    if plan.get("api_key_id") != key_row.get("id"):
        _finalize("failed", "forbidden", "Vacation plan not owned by this API key.")
        return _err("UNAUTHORIZED", "Vacation plan not owned by this API key.", request_id=req_id)

    if plan.get("status") not in ("draft", "planning"):
        _finalize("failed", "read_only", "Vacation plan items are read-only once the plan is ready/cancelled/failed.")
        return _err("CONFLICT", "Vacation plan items are read-only once the plan is ready/cancelled/failed.", request_id=req_id)

    locs_raw = _load("locations.json")
    locs = _rows(locs_raw)
    if location_id is not None:
        loc_ok = False
        for lr in locs:
            if isinstance(lr, dict) and lr.get("id") == location_id:
                loc_ok = True
                break
        if not loc_ok:
            _finalize("failed", "not_found", "Referenced location_id does not exist.")
            return _err("NOT_FOUND", "Referenced location_id does not exist.", request_id=req_id)

    items_raw = _load("vacation_plan_items.json")
    items = _rows(items_raw)

    # datastore constraints: sequence >= 1; day_index >= 1 (or null).
    # tool uses 0-based; convert to datastore 1-based for storage.
    store_day_index = day_index + 1
    store_sequence = sequence + 1

    # Ensure uniqueness(vacation_plan_id, day_index, sequence)
    def _conflict_exists(exclude_id=None):
        for it in items:
            if not isinstance(it, dict):
                continue
            if it.get("vacation_plan_id") != vacation_plan_id:
                continue
            if it.get("day_index") == store_day_index and it.get("sequence") == store_sequence:
                if exclude_id is None or it.get("id") != exclude_id:
                    return True
        return False

    store_item_type = item_type_map[item_type]

    if vacation_plan_item_id is None:
        # create
        if _conflict_exists(exclude_id=None):
            _finalize("failed", "conflict", "An item already exists at this (day_index, sequence).")
            return _err("CONFLICT", "An item already exists at this (day_index, sequence).", request_id=req_id)

        new_id = _gen_id("titem")
        new_item_status = status if status is not None else "proposed"
        item = {
            "id": new_id,
            "vacation_plan_id": vacation_plan_id,
            "day_index": store_day_index,
            "sequence": store_sequence,
            "item_type": store_item_type,
            "location_id": location_id,
            "title": title,
            "starts_at": starts_iso,
            "ends_at": ends_iso,
            "notes": notes,
            "status": new_item_status,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        items.append(item)
        _save_rows("vacation_plan_items.json", items)
        _finalize("succeeded", None, None)
        return {"vacation_plan_item": item, "request_id": req_id}

    # update existing
    existing = None
    for it in items:
        if isinstance(it, dict) and it.get("id") == vacation_plan_item_id:
            existing = it
            break
    if existing is None:
        _finalize("failed", "not_found", "Vacation plan item not found.")
        return _err("NOT_FOUND", "Vacation plan item not found.", request_id=req_id)

    # must belong to plan
    if existing.get("vacation_plan_id") != vacation_plan_id:
        _finalize("failed", "not_found", "Vacation plan item not found in this plan.")
        return _err("NOT_FOUND", "Vacation plan item not found in this plan.", request_id=req_id)

    if _conflict_exists(exclude_id=existing.get("id")):
        _finalize("failed", "conflict", "An item already exists at this (day_index, sequence).")
        return _err("CONFLICT", "An item already exists at this (day_index, sequence).", request_id=req_id)

    # status transition enforcement (if provided)
    if status is not None:
        cur = existing.get("status")
        if cur not in allowed_item_status:
            _finalize("failed", "invalid_transition", f"Item is in an unknown status '{cur}'.")
            return _err("INVALID_TRANSITION", f"Item is in an unknown status '{cur}'.", request_id=req_id)
        if status != cur and status not in transitions.get(cur, set()):
            _finalize("failed", "invalid_transition", f"Cannot transition item from {cur} to {status}.")
            return _err("INVALID_TRANSITION", f"Cannot transition item from {cur} to {status}.", request_id=req_id)
        existing["status"] = status

    # update mutable fields
    existing["day_index"] = store_day_index
    existing["sequence"] = store_sequence
    existing["item_type"] = store_item_type
    existing["location_id"] = location_id
    existing["title"] = title
    existing["starts_at"] = starts_iso
    existing["ends_at"] = ends_iso
    existing["notes"] = notes
    existing["updated_at"] = now_iso

    _save_rows("vacation_plan_items.json", items)
    _finalize("succeeded", None, None)
    return {"vacation_plan_item": existing, "request_id": req_id}

def list_vacation_plan_items(api_key, vacation_plan_id, day_index=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0450000" if __import__("os").path.isdir("./environment_mix/0450000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _find_api_key(keys, presented):
        if not isinstance(presented, str) or not presented.strip():
            return None
        presented = presented.strip()
        for k in keys:
            if k.get("id") == presented:
                return k
        for k in keys:
            if k.get("key_hash") == presented:
                return k
        return None

    def _reset_usage_window_if_needed(krow):
        try:
            w = krow.get("usage_window_start")
            if isinstance(w, str):
                if w.endswith("Z"):
                    wdt = datetime.datetime.fromisoformat(w[:-1]).replace(tzinfo=datetime.timezone.utc)
                else:
                    wdt = datetime.datetime.fromisoformat(w)
                    if wdt.tzinfo is None:
                        wdt = wdt.replace(tzinfo=datetime.timezone.utc)
            elif isinstance(w, datetime.datetime):
                wdt = w
            else:
                wdt = _now()
        except Exception:
            wdt = _now()
        n = _now()
        if wdt.astimezone(datetime.timezone.utc).date() != n.astimezone(datetime.timezone.utc).date():
            krow["usage_window_start"] = _iso(datetime.datetime(n.year, n.month, n.day, tzinfo=datetime.timezone.utc))
            krow["daily_requests_used"] = 0

    def _gen_id(prefix):
        raw = f"{prefix}_{_iso(_now())}_{os.getpid()}_{time.time_ns()}"
        h = hashlib.sha256(raw.encode("utf-8")).digest()
        tok = base64.urlsafe_b64encode(h[:12]).decode("ascii").rstrip("=")
        return f"{prefix}_{tok}"

    def _log_request(reqs, api_key_id, tool_name, initial_fields):
        now = _now()
        rid = _gen_id("lsr")
        row = {
            "id": rid,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "latitude": None,
            "longitude": None,
            "category": None,
            "location_id": None,
            "status": "received",
            "error_code": None,
            "error_message": None,
            "response_count": None,
            "latency_ms": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        row.update(initial_fields or {})
        reqs.append(row)
        return row

    def _finalize_log(row, status, latency_ms, response_count=None, error_code=None, error_message=None):
        now = _now()
        row["status"] = status
        row["latency_ms"] = int(latency_ms) if latency_ms is not None else None
        row["response_count"] = response_count
        row["error_code"] = error_code
        row["error_message"] = error_message
        row["updated_at"] = _iso(now)

    def _decode_cursor(cur):
        if not cur:
            return 0
        if not isinstance(cur, str):
            return None
        try:
            pad = "=" * (-len(cur) % 4)
            data = base64.urlsafe_b64decode((cur + pad).encode("ascii")).decode("utf-8")
            if not data.startswith("o:"):
                return None
            return int(data.split(":", 1)[1])
        except Exception:
            return None

    def _encode_cursor(offset):
        s = f"o:{int(offset)}".encode("utf-8")
        return base64.urlsafe_b64encode(s).decode("ascii").rstrip("=")

    # ---------- validate inputs ----------
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required")
    if not isinstance(vacation_plan_id, str) or not re.match(r"^[A-Za-z0-9_-]+$", vacation_plan_id):
        return _err("VALIDATION_ERROR", "vacation_plan_id must match ^[A-Za-z0-9_-]+$")
    if day_index is not None and (not isinstance(day_index, int) or day_index < 0):
        return _err("VALIDATION_ERROR", "day_index must be an integer >= 0")
    if status is not None and (not isinstance(status, str) or status not in {"proposed", "confirmed", "removed"}):
        return _err("VALIDATION_ERROR", "status must be one of proposed, confirmed, removed")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    offset = _decode_cursor(cursor)
    if offset is None:
        return _err("VALIDATION_ERROR", "Invalid cursor")

    # ---------- load store ----------
    api_keys = _load("api_keys.json")
    plans = _load("vacation_plans.json")
    items = _load("vacation_plan_items.json")
    reqs = _load("location_search_requests.json")

    # ---------- authenticate ----------
    keyrow = _find_api_key(api_keys, api_key)
    if not keyrow:
        return _err("UNAUTHORIZED", "Invalid API key")

    # log received
    log_row = _log_request(reqs, keyrow["id"], "plan_vacation", {})

    # enforce key status
    if keyrow.get("status") != "active":
        _finalize_log(log_row, "failed", (time.time() - _t0) * 1000, error_code="key_inactive", error_message="API key is not active")
        _save("location_search_requests.json", reqs)
        return _err("UNAUTHORIZED", "API key is not active")

    # enforce quota (reads count as requests per business rule that every invocation is logged and usage enforced)
    _reset_usage_window_if_needed(keyrow)
    try:
        limit_q = int(keyrow.get("daily_request_limit"))
        used = int(keyrow.get("daily_requests_used"))
    except Exception:
        _finalize_log(log_row, "failed", (time.time() - _t0) * 1000, error_code="invalid_key_quota", error_message="API key quota configuration invalid")
        _save("location_search_requests.json", reqs)
        return _err("FAILED", "API key quota configuration invalid")

    if used >= limit_q:
        _finalize_log(log_row, "rate_limited", (time.time() - _t0) * 1000, error_code="daily_quota_exceeded", error_message="Daily request limit exceeded")
        _save("location_search_requests.json", reqs)
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded", daily_request_limit=limit_q, daily_requests_used=used)

    # ---------- plan existence + ownership ----------
    plan = next((p for p in plans if p.get("id") == vacation_plan_id), None)
    if not plan:
        _finalize_log(log_row, "failed", (time.time() - _t0) * 1000, error_code="plan_not_found", error_message="Vacation plan not found")
        _save("location_search_requests.json", reqs)
        return _err("NOT_FOUND", "Vacation plan not found")

    if plan.get("api_key_id") != keyrow.get("id"):
        _finalize_log(log_row, "failed", (time.time() - _t0) * 1000, error_code="forbidden", error_message="Vacation plan not owned by this API key")
        _save("location_search_requests.json", reqs)
        return _err("UNAUTHORIZED", "Vacation plan not owned by this API key")

    # ---------- filter/sort/paginate ----------
    mapped_day = (day_index + 1) if day_index is not None else None

    filtered = []
    for it in items:
        if it.get("vacation_plan_id") != vacation_plan_id:
            continue
        if mapped_day is not None and it.get("day_index") != mapped_day:
            continue
        if status is not None and it.get("status") != status:
            continue
        filtered.append(it)

    filtered.sort(key=lambda r: (
        r.get("day_index") if isinstance(r.get("day_index"), int) else 10**9,
        r.get("sequence") if isinstance(r.get("sequence"), int) else 10**9,
        r.get("id") or "",
    ))

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    # update usage + logs
    now = _now()
    keyrow["daily_requests_used"] = used + 1
    keyrow["last_used_at"] = _iso(now)
    keyrow["updated_at"] = _iso(now)

    _save("api_keys.json", api_keys)
    _finalize_log(log_row, "succeeded", (time.time() - _t0) * 1000, response_count=len(page))
    _save("location_search_requests.json", reqs)

    # map to tool schema (0-based, tool item_type mapping)
    type_map = {
        "hotel": "lodging",
        "restaurant": "meal",
        "attraction": "activity",
        "transport": "transport",
        "note": "free_time",
        "other": "other",
    }
    out_items = []
    for it in page:
        o = dict(it)
        if isinstance(o.get("day_index"), int):
            o["day_index"] = o["day_index"] - 1
        if isinstance(o.get("sequence"), int):
            o["sequence"] = o["sequence"] - 1
        o["item_type"] = type_map.get(o.get("item_type"), "other")
        out_items.append(o)

    return {
        "vacation_plan_id": vacation_plan_id,
        "items": out_items,
        "page": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": total,
        },
    }
